const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const [n_str, k_str] = line.trim().split(' ');
    const n = parseInt(n_str);
    const k = parseInt(k_str);

    // Calculate factorial for numbers up to 20 (enough for 1e9)
    // 13! = 6227020800 > 1e9
    const MAX_FACT = 20;
    const fact = new Array(MAX_FACT + 1).fill(1);
    for (let i = 1; i <= MAX_FACT; i++) {
        fact[i] = fact[i - 1] * i;
    }

    // Check if k-th permutation exists
    let total_perms;
    if (n <= MAX_FACT) {
        total_perms = fact[n];
    } else {
        // n > 20, n! is huge > 1e9
        total_perms = k + 1; // effectively infinity
    }

    if (k > total_perms) {
        console.log(-1);
        return;
    }

    // Generate lucky numbers up to n
    const luckyNumbers = [];
    function generateLucky(current) {
        if (current > n) return;
        if (current > 0) luckyNumbers.push(current);
        generateLucky(current * 10 + 4);
        generateLucky(current * 10 + 7);
    }
    generateLucky(0);
    luckyNumbers.sort((a, b) => a - b);

    // Create a Set for O(1) lookup
    const luckySet = new Set(luckyNumbers);

    // Determine the suffix size m
    // We need the smallest m such that m! >= k
    let m = 0;
    while (m <= MAX_FACT && fact[m] < k) {
        m++;
    }
    // m is the suffix length.
    // The first n - m elements are fixed: a[i] = i.
    // The last m elements are a permutation of {n-m+1, ..., n}.

    // Count lucky indices i where i is lucky and a[i] is lucky.
    // Case 1: i is in the fixed prefix (1 <= i <= n - m)
    // Here a[i] = i. So we need i to be lucky.
    let count = 0;
    for (const ln of luckyNumbers) {
        if (ln <= n - m) {
            count++;
        } else {
            break;
        }
    }

    // Case 2: i is in the variable suffix (n - m + 1 <= i <= n)
    // We need to generate the (k-1)-th permutation (0-indexed) of the suffix elements.
    const suffix_elements = [];
    for (let i = n - m + 1; i <= n; i++) {
        suffix_elements.push(i);
    }

    let current_k = k - 1; // 0-indexed
    // Construct the permutation for the suffix
    // We only care about positions corresponding to lucky numbers.
    // However, m <= 13, so we can just generate the whole suffix permutation.
    const suffix_perm = [];
    const available = [...suffix_elements];

    for (let i = m; i >= 1; i--) {
        const f = fact[i - 1];
        const index = Math.floor(current_k / f);
        current_k %= f;
        suffix_perm.push(available.splice(index, 1)[0]);
    }

    // Check positions in suffix
    // Global index i = (n - m) + j, where j is 1..m
    // Value = suffix_perm[j-1]
    for (let j = 1; j <= m; j++) {
        const globalIndex = n - m + j;
        const value = suffix_perm[j - 1];
        if (luckySet.has(globalIndex) && luckySet.has(value)) {
            count++;
        }
    }

    console.log(count);
});
